const data = msg.payload;

// 1. Vérifier les données reçues
if (
    !data ||
    typeof data !== "object" ||
    Array.isArray(data) ||
    !data.sensorId ||
    !data.sensorType ||
    data.value === undefined ||
    !data.unit ||
    !data.timestamp
) {
    msg.validationError = "Missing required fields";
    return [null, msg];
}

// 2. Vérifier le topic MQTT dans msg.topic
if (
    typeof msg.topic !== "string" ||
    msg.topic.length === 0
) {
    msg.validationError = "Missing or invalid MQTT topic";
    return [null, msg];
}

// 3. Vérifier la valeur du capteur
if (
    typeof data.value !== "number" ||
    !Number.isFinite(data.value)
) {
    msg.validationError = "Invalid sensor value";
    return [null, msg];
}

// 4. Vérifier le timestamp
if (
    typeof data.timestamp !== "string" ||
    isNaN(Date.parse(data.timestamp))
) {
    msg.validationError = "Invalid timestamp";
    return [null, msg];
}

// 5. Message valide
msg.valid = true;
return [msg, null];

// Enrich Data — builds the telemetry message according to contract §2.1
const data = msg.payload;

if (
    !data ||
    typeof data !== "object" ||
    !data.sensorId ||
    !data.sensorType ||
    data.value === undefined ||
    !data.unit ||
    !data.timestamp
) {
    node.error("Invalid telemetry data: missing required fields", msg);
    return null;
}

// Expected MQTT topic: building/B1/2/R203/co2
const parts = String(msg.topic || "").split("/");

if (parts.length !== 5 || parts[0] !== "building") {
    node.error("Invalid MQTT topic: " + msg.topic, msg);
    return null;
}

const floor = Number(parts[2]);

const zones = {
    1: "reception",
    2: "offices",
    3: "meeting"
};

if (!zones[floor]) {
    node.error("Invalid floor: " + parts[2], msg);
    return null;
}

function uuid() {
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
        const r = Math.random() * 16 | 0;
        return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16);
    });
}

// Create a new object containing exactly the contract fields, in the specified order
msg.payload = {
    schemaVersion: 1,
    messageId: uuid(),
    sensorId: data.sensorId,
    buildingId: parts[1],
    floor: floor,
    room: parts[3],
    zone: zones[floor],
    sensorType: parts[4],
    value: Number(data.value),
    unit: data.unit,
    status: "ok", // Recalculated by Calculate Alert Thresholds
    timestamp: data.timestamp,
    processedAt: new Date().toISOString()
};

msg.key = parts[3]; // Kafka key = room (contract §2)
return msg;

const data = msg.payload;

// Preserve the original message and add rejection metadata
const invalidMessage = (data && typeof data === "object" && !Array.isArray(data))
    ? { ...data }
    : { originalPayload: data };

invalidMessage.error = msg.validationError || "Invalid message";
invalidMessage.receivedAt = new Date().toISOString();

msg.payload = invalidMessage;

return msg;

const data = msg.payload;

// ==================================================
// 1. Validate incoming data
// ==================================================

if (!data || typeof data !== "object" || Array.isArray(data)) {
    node.warn("Alert rejected: invalid payload");
    return null;
}

// ==================================================
// 2. Validate alert severity
// ==================================================

const severity = String(data.status || data.severity || "").toLowerCase();

if (!data.sensorId || !["warning", "critical"].includes(severity)) {
    node.warn("Alert rejected: invalid sensorId or severity");
    return null;
}

// ==================================================
// 3. Validate required fields
// ==================================================

const required = [
    "floor",
    "room",
    "sensorType",
    "value",
    "timestamp",
    "threshold"
];

for (const field of required) {
    if (
        data[field] === undefined ||
        data[field] === null ||
        data[field] === ""
    ) {
        node.warn(`Alert rejected: missing ${field}`);
        return null;
    }
}

// ==================================================
// 4. Determine zone from floor
// ==================================================

const zones = {
    1: "reception",
    2: "offices",
    3: "meeting"
};

const floor = Number(data.floor);
const zone = zones[floor];

if (!Number.isInteger(floor) || !zone) {
    node.warn(`Alert rejected: invalid floor ${data.floor}`);
    return null;
}

// ==================================================
// 5. Validate threshold
// ==================================================

const threshold = Number(data.threshold);
const value = Number(data.value);

if (!Number.isFinite(threshold) || !Number.isFinite(value)) {
    node.warn("Alert rejected: invalid value or threshold");
    return null;
}

// ==================================================
// 6. Anti-spam: one alert per sensor/severity
//    every 60 seconds
// ==================================================

const now = Date.now();
const key = `alert_${data.sensorId}_${severity}`;
const lastSent = context.get(key) || 0;

if (now - lastSent < 60000) {
    node.warn(`Alert suppressed by anti-spam: ${data.sensorId}`);
    return null;
}

// ==================================================
// 7. Build the alert payload
//    Exactly 12 fields (Contract §2.2)
// ==================================================

const alert = {
    alertId: `${data.sensorId}-${severity}-${now}`,
    schemaVersion: 1,
    sensorId: data.sensorId,
    floor: floor,
    room: data.room,
    zone: zone,
    sensorType: data.sensorType,
    value: value,
    threshold: threshold,
    severity: severity,
    message: `${data.sensorType} ${severity} in ${data.room}: ${value}`,
    timestamp: data.timestamp
};

// ==================================================
// 8. Save anti-spam timestamp
// ==================================================

context.set(key, now);

// ==================================================
// 9. Prepare Kafka message
// ==================================================

msg.topic = "building.alerts";
msg.payload = alert;
msg.qos = 1;
msg.retain = false;
msg.key = data.room;
return msg;

const data = msg.payload;

// ==================================================
// 1. Validate incoming telemetry
// ==================================================

if (!data || typeof data !== "object" || Array.isArray(data)) {
    return reject("Invalid telemetry payload");
}

if (
    !data.sensorId ||
    !data.room ||
    !data.sensorType ||
    data.value === undefined ||
    data.value === null ||
    !data.timestamp
) {
    return reject("Missing required telemetry field");
}

const value = Number(data.value);
const type = String(data.sensorType).toLowerCase();

if (!Number.isFinite(value)) {
    return reject("Sensor value must be a valid number");
}

// ==================================================
// 2. Validate physical limits
// Invalid measurements go to building.invalid
// ==================================================

const physicalLimits = {
    temperature: { min: -40, max: 80 },
    humidity: { min: 0, max: 100 },
    co2: { min: 0, max: 10000 },
    occupancy: { min: 0, max: 200 },
    energy: { min: 0, max: 100 }
};

if (!physicalLimits[type]) {
    return reject("Unknown sensor type");
}

const limits = physicalLimits[type];

if (value < limits.min || value > limits.max) {
    return reject("Sensor value outside physical limits");
}

if (type === "occupancy" && !Number.isInteger(value)) {
    return reject("Occupancy value must be an integer");
}

// ==================================================
// 3. Calculate alert thresholds
// ==================================================

let status = "ok";
let threshold = null;

// Temperature
if (type === "temperature") {

    if (value > 28) {
        status = "critical";
        threshold = 28;
    } else if (value < 16) {
        status = "critical";
        threshold = 16;
    } else if (value > 26) {
        status = "warning";
        threshold = 26;
    } else if (value < 18) {
        status = "warning";
        threshold = 18;
    }
}

// Humidity
else if (type === "humidity") {

    if (value > 75) {
        status = "critical";
        threshold = 75;
    } else if (value < 20) {
        status = "critical";
        threshold = 20;
    } else if (value > 65) {
        status = "warning";
        threshold = 65;
    } else if (value < 25) {
        status = "warning";
        threshold = 25;
    }
}

// CO2
else if (type === "co2") {

    if (value > 1500) {
        status = "critical";
        threshold = 1500;
    } else if (value > 1000) {
        status = "warning";
        threshold = 1000;
    }
}

// Occupancy
else if (type === "occupancy") {

    const date = new Date(data.timestamp);

    if (Number.isNaN(date.getTime())) {
        return reject("Invalid timestamp");
    }

    const hour = Number(
        new Intl.DateTimeFormat("en-GB", {
            timeZone: "Europe/Madrid",
            hour: "2-digit",
            hourCycle: "h23"
        }).format(date)
    );

    if (value > 0 && (hour >= 22 || hour < 6)) {
        status = "critical";
        threshold = 0;
    }
}

// Energy
else if (type === "energy") {

    if (value > 5) {
        status = "critical";
        threshold = 5;
    } else if (value > 3) {
        status = "warning";
        threshold = 3;
    }
}

// ==================================================
// 4. Enrich telemetry with threshold results
// ==================================================

data.sensorType = type;
data.value = value;
data.status = status;
data.threshold = threshold;

msg.payload = data;

// ==================================================
// 5. Send valid telemetry to the Switch
// ==================================================

return [msg, null];

// ==================================================
// 6. Route invalid telemetry to building.invalid
// ==================================================

function reject(reason) {

    const invalidMsg = {
        ...msg,
        payload: {
            ...data,
            error: reason,
            receivedAt: new Date().toISOString()
        },
        topic: "building.invalid",
        qos: 1,
        retain: false
    };

    return [null, invalidMsg];
}

// Ventilation Control — CO2 control loop (day 7) //
// Input : telemetry from "Calculate Alert Thresholds" (output 1) 
// Output: MQTT command on cmd/{building}/{floor}/{room}/ventilation (contract §1.2) 
const d = msg.payload; 
if (!d || d.sensorType !== "co2") {  
  return null;                        // only CO2 drives the ventilation 
} 
const ON_ABOVE = 1500;                  // critical threshold (contract §3) -> switch on
const OFF_BELOW = 800;                  // back to a healthy level -> switch off 
const key = "ventilation_" + d.room; 
const state = context.get(key);         // true = on, false = off, undefined = unknown 
let action = null; 
let reason = null; 
if (state !== true && d.value > ON_ABOVE) {  
    action = "on"; 
    reason = "co2_critical"; 
} 
else if (state !== false && d.value < OFF_BELOW) {
    action = "off";
    reason = "co2_normal"; 
}
 if (action === null) {   
     return null;                        // nothing changes: no command
}
context.set(key, action === "on");
node.status({
    fill: action === "on" ? "red" : "green", 
    shape: "dot",
    text: d.room + " ventilation " + action 
});
 return {
    topic: "cmd/" + d.buildingId + "/" + d.floor + "/" + d.room + "/ventilation",
    payload: {
        action: action,
        reason: reason,
        timestamp: new Date().toISOString()
    },
    qos: 1, 
   retain: false };
